BEGIN;
CREATE SCHEMA erp_credit_private;
REVOKE ALL ON SCHEMA erp_credit_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_credit_types(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150),unit text NOT NULL DEFAULT '' CHECK(length(unit)<=30),description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),active boolean NOT NULL DEFAULT true,decimals boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,id),UNIQUE(cafe_id,name));
CREATE TABLE public.erp_credit_packages(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150),kind text NOT NULL CHECK(kind IN('membership','credit')),price numeric(14,2) NOT NULL CHECK(price BETWEEN 0 AND 1e9),period integer NOT NULL CHECK(period BETWEEN 1 AND 3650),period_unit text NOT NULL CHECK(period_unit IN('day','week','month','year')),description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,id),UNIQUE(cafe_id,name));
CREATE TABLE public.erp_credit_package_lines(cafe_id uuid NOT NULL,package_id uuid NOT NULL,type_id uuid NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity>0),position integer NOT NULL,PRIMARY KEY(cafe_id,package_id,type_id),FOREIGN KEY(cafe_id,package_id) REFERENCES public.erp_credit_packages(cafe_id,id) ON DELETE CASCADE,FOREIGN KEY(cafe_id,type_id) REFERENCES public.erp_credit_types(cafe_id,id));
CREATE TABLE public.erp_credit_charges(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,customer_id uuid NOT NULL,type_id uuid NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity>0 AND quantity<=1e12),starts_on date NOT NULL,expires_on date,description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),suspended boolean NOT NULL DEFAULT false,source_kind text NOT NULL DEFAULT 'manual',source_id uuid,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(cafe_id,id),CHECK(expires_on IS NULL OR expires_on>=starts_on),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,type_id) REFERENCES public.erp_credit_types(cafe_id,id));
CREATE TABLE public.erp_credit_usages(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL,number bigint GENERATED BY DEFAULT AS IDENTITY,customer_id uuid NOT NULL,type_id uuid NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity>0 AND quantity<=1e12),used_on date NOT NULL,description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),charge_id uuid,voided boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES auth.users(id),PRIMARY KEY(cafe_id,id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,type_id) REFERENCES public.erp_credit_types(cafe_id,id),FOREIGN KEY(cafe_id,charge_id) REFERENCES public.erp_credit_charges(cafe_id,id));
CREATE TABLE public.erp_credit_allocations(cafe_id uuid NOT NULL,usage_id uuid NOT NULL,charge_id uuid NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity>0),PRIMARY KEY(cafe_id,usage_id,charge_id),FOREIGN KEY(cafe_id,usage_id) REFERENCES public.erp_credit_usages(cafe_id,id),FOREIGN KEY(cafe_id,charge_id) REFERENCES public.erp_credit_charges(cafe_id,id));
CREATE TABLE public.erp_credit_events(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL,action text NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),at timestamptz NOT NULL DEFAULT now());
CREATE TABLE erp_credit_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,input jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE INDEX ON public.erp_credit_charges(cafe_id,customer_id,type_id,expires_on);
CREATE INDEX ON public.erp_credit_usages(cafe_id,customer_id,used_on);
CREATE INDEX ON public.erp_credit_events(cafe_id,record_id,at);
CREATE INDEX ON public.erp_credit_allocations(cafe_id,charge_id);
DO $$DECLARE d text[];BEGIN d:=erp_access_private.domains();IF NOT('credits'=ANY(d)) THEN d:=d||'credits'::text;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',d);END IF;END $$;
UPDATE public.erp_roles SET permissions=permissions||jsonb_build_object('credits',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false)) WHERE NOT(permissions?'credits');
CREATE FUNCTION erp_credit_private.authorize(c uuid,a text DEFAULT 'read') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=brand_finance_private.role_for(c);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor') OR(a<>'read' AND r='auditor') THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة الأرصدة' USING ERRCODE='42501';END IF;PERFORM erp_access_private.assert_allowed(c,'credits',a);RETURN r;END $$;
CREATE FUNCTION erp_credit_private.remaining(c uuid,i uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT x.quantity-coalesce((SELECT sum(a.quantity) FROM public.erp_credit_allocations a WHERE a.cafe_id=c AND a.charge_id=i),0) FROM public.erp_credit_charges x WHERE x.cafe_id=c AND x.id=i$$;
CREATE FUNCTION public.erp_credits_read(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=erp_credit_private.authorize(p_cafe);RETURN jsonb_build_object(
 'types',coalesce((SELECT jsonb_agg(to_jsonb(t)-'cafe_id' ORDER BY name) FROM public.erp_credit_types t WHERE cafe_id=p_cafe),'[]'::jsonb),
 'packages',coalesce((SELECT jsonb_agg((to_jsonb(p)-'cafe_id'-'period_unit')||jsonb_build_object('periodUnit',period_unit,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('typeId',type_id,'quantity',quantity) ORDER BY position) FROM public.erp_credit_package_lines l WHERE l.cafe_id=p_cafe AND l.package_id=p.id),'[]'::jsonb)) ORDER BY name) FROM public.erp_credit_packages p WHERE cafe_id=p_cafe),'[]'::jsonb),
 'charges',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'revision',revision,'number',number,'customerId',customer_id,'typeId',type_id,'quantity',quantity,'startsOn',starts_on,'expiresOn',coalesce(expires_on::text,''),'description',description,'suspended',suspended,'sourceKind',source_kind,'sourceId',source_id,'createdAt',created_at,'remaining',erp_credit_private.remaining(p_cafe,id)) ORDER BY created_at DESC,number DESC) FROM public.erp_credit_charges x WHERE cafe_id=p_cafe),'[]'::jsonb),
 'usages',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'number',number,'customerId',customer_id,'typeId',type_id,'quantity',quantity,'usedOn',used_on,'description',description,'chargeId',charge_id,'voided',voided,'createdAt',created_at) ORDER BY created_at DESC,number DESC) FROM public.erp_credit_usages WHERE cafe_id=p_cafe),'[]'::jsonb),
 'allocations',coalesce((SELECT jsonb_agg(jsonb_build_object('usageId',usage_id,'chargeId',charge_id,'quantity',quantity)) FROM public.erp_credit_allocations WHERE cafe_id=p_cafe),'[]'::jsonb),
 'customers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'active',active) ORDER BY name) FROM public.bf_parties WHERE cafe_id=p_cafe AND kind='customer'),'[]'::jsonb),
 'events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'recordId',record_id,'action',action,'at',at,'actorName',coalesce(p.name,'')) ORDER BY at DESC) FROM public.erp_credit_events e LEFT JOIN public.bf_staff p ON p.user_id=e.actor AND p.cafe_id=e.cafe_id WHERE e.cafe_id=p_cafe),'[]'::jsonb),
 'today',(now() AT TIME ZONE 'Asia/Riyadh')::date,'canCreate',r<>'auditor' AND erp_access_private.allowed(p_cafe,'credits','create'),'canUpdate',r<>'auditor' AND erp_access_private.allowed(p_cafe,'credits','update'),'canDelete',r<>'auditor' AND erp_access_private.allowed(p_cafe,'credits','delete'),'canSettings',r<>'auditor' AND erp_access_private.allowed(p_cafe,'credits','settings'));
END $$;
CREATE FUNCTION public.erp_credits_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE i uuid;rev integer;old_rev integer;result jsonb;prior erp_credit_private.requests;t public.erp_credit_types;ch public.erp_credit_charges;u public.erp_credit_usages;cu uuid;ty uuid;qty numeric;d date;ex date;line jsonb;n integer;row record;need numeric;take numeric;permission text;
BEGIN
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>100000 OR p_action NOT IN('type','type_delete','package','package_delete','charge','charge_delete','usage','usage_delete') THEN RAISE EXCEPTION 'راجع بيانات عملية الرصيد';END IF;
 i:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;IF i IS NULL OR rev IS NULL OR rev<0 THEN RAISE EXCEPTION 'معرف السجل غير صالح';END IF;
 permission:=CASE WHEN p_action LIKE '%_delete' THEN 'delete' WHEN rev=0 THEN 'create' ELSE 'update' END;PERFORM erp_credit_private.authorize(p_cafe,permission);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));
 SELECT * INTO prior FROM erp_credit_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_action LIKE 'type%' THEN
  SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(t.revision,0);IF old_rev<>rev THEN RAISE EXCEPTION 'تغير نوع الرصيد' USING ERRCODE='40001';END IF;
  IF p_action='type_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'نوع الرصيد غير موجود';END IF;DELETE FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'decimals') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الحالة ووحدات الرصيد';END IF;
   IF NOT(p_input->>'decimals')::boolean AND(EXISTS(SELECT 1 FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity)) OR EXISTS(SELECT 1 FROM public.erp_credit_package_lines WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity)) OR EXISTS(SELECT 1 FROM public.erp_credit_usages WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity))) THEN RAISE EXCEPTION 'لا يمكن إلغاء الكسور لنوع مرتبط بكميات عشرية';END IF;
   INSERT INTO public.erp_credit_types(cafe_id,id,name,unit,description,active,decimals,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),coalesce(p_input->>'unit',''),coalesce(p_input->>'description',''),(p_input->>'active')::boolean,(p_input->>'decimals')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,unit=excluded.unit,description=excluded.description,active=excluded.active,decimals=excluded.decimals,revision=excluded.revision;
  END IF;
 ELSIF p_action LIKE 'package%' THEN
  SELECT revision INTO old_rev FROM public.erp_credit_packages WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت الباقة' USING ERRCODE='40001';END IF;
  IF p_action='package_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الباقة غير موجودة';END IF;DELETE FROM public.erp_credit_packages WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'lines')>100 OR ((p_input->>'kind')='credit' AND jsonb_array_length(p_input->'lines')=0) OR (p_input->>'price')::numeric<>round((p_input->>'price')::numeric,2) THEN RAISE EXCEPTION 'راجع معلومات الباقة وأنواع الأرصدة';END IF;
   INSERT INTO public.erp_credit_packages(cafe_id,id,name,kind,price,period,period_unit,description,active,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),p_input->>'kind',(p_input->>'price')::numeric,(p_input->>'period')::integer,p_input->>'periodUnit',coalesce(p_input->>'description',''),(p_input->>'active')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,kind=excluded.kind,price=excluded.price,period=excluded.period,period_unit=excluded.period_unit,description=excluded.description,active=excluded.active,revision=excluded.revision;
   DELETE FROM public.erp_credit_package_lines WHERE cafe_id=p_cafe AND package_id=i;n:=0;
   FOR line IN SELECT value FROM jsonb_array_elements(p_input->'lines') LOOP n:=n+1;ty:=(line->>'typeId')::uuid;qty:=(line->>'quantity')::numeric;SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=ty AND active;IF NOT FOUND OR qty IS NULL OR qty<=0 OR qty>1e12 OR qty<>round(qty,4) OR(NOT t.decimals AND qty<>trunc(qty)) THEN RAISE EXCEPTION 'راجع نوع الرصيد والكمية وسماح الكسور';END IF;INSERT INTO public.erp_credit_package_lines VALUES(p_cafe,i,ty,qty,n);END LOOP;
  END IF;
 ELSE
  IF p_action LIKE 'charge%' THEN SELECT * INTO ch FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(ch.revision,0);IF ch.id IS NOT NULL AND ch.source_kind<>'manual' THEN RAISE EXCEPTION 'الشحنة مرتبطة باشتراك وتدار من مصدرها';END IF;
  ELSE SELECT * INTO u FROM public.erp_credit_usages WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(u.revision,0);IF u.voided THEN RAISE EXCEPTION 'تم إلغاء حركة الاستهلاك';END IF;END IF;
  IF old_rev<>rev THEN RAISE EXCEPTION 'تغير سجل الرصيد' USING ERRCODE='40001';END IF;
  IF p_action='charge_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الشحنة غير موجودة';END IF;DELETE FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='usage_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الاستهلاك غير موجود';END IF;DELETE FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND usage_id=i;UPDATE public.erp_credit_usages SET voided=true,revision=rev+1 WHERE cafe_id=p_cafe AND id=i;
  ELSE
   cu:=(p_input->>'customerId')::uuid;ty:=(p_input->>'typeId')::uuid;qty:=(p_input->>'quantity')::numeric;
   IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=cu AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
   SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=ty AND active;IF NOT FOUND OR qty IS NULL OR qty<=0 OR qty>1e12 OR qty<>round(qty,4) OR(NOT t.decimals AND qty<>trunc(qty)) THEN RAISE EXCEPTION 'راجع نوع الرصيد والكمية وسماح الكسور';END IF;
   IF p_action='charge' THEN
    d:=(p_input->>'startsOn')::date;ex:=nullif(p_input->>'expiresOn','')::date;IF d IS NULL OR NOT isfinite(d) OR (ex IS NOT NULL AND NOT isfinite(ex)) THEN RAISE EXCEPTION 'راجع تواريخ الشحنة';END IF;IF jsonb_typeof(p_input->'suspended') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع حالة الشحنة';END IF;
    IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages v ON v.cafe_id=a.cafe_id AND v.id=a.usage_id WHERE a.cafe_id=p_cafe AND a.charge_id=i AND(v.customer_id<>cu OR v.type_id<>ty OR v.used_on<d OR v.used_on>ex)) OR qty<coalesce((SELECT sum(quantity) FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND charge_id=i),0) THEN RAISE EXCEPTION 'التعديل يتعارض مع الاستهلاك المسجل';END IF;
    INSERT INTO public.erp_credit_charges(cafe_id,id,customer_id,type_id,quantity,starts_on,expires_on,description,suspended,revision,created_by) VALUES(p_cafe,i,cu,ty,qty,d,ex,coalesce(p_input->>'description',''),(p_input->>'suspended')::boolean,rev+1,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET customer_id=excluded.customer_id,type_id=excluded.type_id,quantity=excluded.quantity,starts_on=excluded.starts_on,expires_on=excluded.expires_on,description=excluded.description,suspended=excluded.suspended,revision=excluded.revision;
   ELSE
    d:=(p_input->>'usedOn')::date;IF d IS NULL OR NOT isfinite(d) THEN RAISE EXCEPTION 'راجع تاريخ الاستهلاك';END IF;DELETE FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND usage_id=i;
    INSERT INTO public.erp_credit_usages(cafe_id,id,customer_id,type_id,quantity,used_on,description,charge_id,revision,created_by) VALUES(p_cafe,i,cu,ty,qty,d,coalesce(p_input->>'description',''),nullif(p_input->>'chargeId','')::uuid,rev+1,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET customer_id=excluded.customer_id,type_id=excluded.type_id,quantity=excluded.quantity,used_on=excluded.used_on,description=excluded.description,charge_id=excluded.charge_id,revision=excluded.revision;
    need:=qty;FOR row IN SELECT x.id FROM public.erp_credit_charges x WHERE x.cafe_id=p_cafe AND x.customer_id=cu AND x.type_id=ty AND NOT x.suspended AND x.starts_on<=d AND(x.expires_on IS NULL OR x.expires_on>=d) AND(nullif(p_input->>'chargeId','') IS NULL OR x.id=(p_input->>'chargeId')::uuid) ORDER BY x.expires_on ASC NULLS LAST,x.starts_on,x.number FOR UPDATE LOOP take:=least(need,erp_credit_private.remaining(p_cafe,row.id));IF take>0 THEN INSERT INTO public.erp_credit_allocations VALUES(p_cafe,i,row.id,take);need:=need-take;END IF;EXIT WHEN need=0;END LOOP;
    IF need>0 THEN RAISE EXCEPTION 'الرصيد المتاح لا يكفي للاستهلاك المطلوب';END IF;
   END IF;
  END IF;
 END IF;
 INSERT INTO public.erp_credit_events(cafe_id,record_id,action,actor) VALUES(p_cafe,i,p_action,auth.uid());result:=jsonb_build_object('id',i,'revision',rev+1,'deleted',p_action LIKE '%_delete');INSERT INTO erp_credit_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_credit_types','erp_credit_packages','erp_credit_package_lines','erp_credit_charges','erp_credit_usages','erp_credit_allocations','erp_credit_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_credit_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_credits_read(uuid),public.erp_credits_write(uuid,text,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_credits_read(uuid),public.erp_credits_write(uuid,text,jsonb,uuid) TO authenticated;
COMMIT;
